.shopify-pc__banner__dialog h2 {
  color: hsl(0deg, 0%, 12%, 100%);
  font-family: inherit;
  font-size: 120%;
  margin: 0 0 .5em 0;
  padding: 0;
  font-weight: bold;
}
.shopify-pc__banner__dialog p {
  color: hsl(0deg, 0%, 12%, 100%);
  font-family: inherit;
  line-height: 1.3;
  margin: 0;
  padding: 0;
}
.shopify-pc__banner__dialog a {
  color: hsl(0deg, 0%, 12%, 100%);
  text-decoration: underline;
}
.shopify-pc__banner__dialog button {
  border: none;
  text-decoration: none;
  font-family: inherit;
  padding: 8px 25px;
  /* RTL mirrors this margin in getCSSForBannerPlacement (rtlDefaultButtons). */
  margin: 15px 20px 0 0;
  font-size: 100%;
  flex-basis: 50%;
  border-radius: 2px;
  line-height: 120%;
  height: unset;
  text-align: center;
}
.shopify-pc__banner__dialog button:focus {
  outline: none;
  box-shadow: 0 0 0 4px hsl(201deg, 90%, 80%, 100%);
}
.shopify-pc__banner__dialog button:hover {
  cursor: pointer;
}
.shopify-pc__banner__dialog button.shopify-pc__banner__btn-accept {
  border: 1px solid hsl(0deg, 0%, 12%, 100%);

background: #fff;
color: #333;

}
.shopify-pc__banner__dialog button.shopify-pc__banner__btn-manage-prefs {
  text-decoration: underline;

background: transparent;
border: none;
color: #333;

}
.shopify-pc__banner__dialog button.shopify-pc__banner__btn-manage-prefs:focus {
  box-shadow: none;
}
.shopify-pc__banner__dialog button.shopify-pc__banner__btn-manage-prefs:focus span {
  outline: 2px solid hsl(201deg, 90%, 80%, 100%);
}
.shopify-pc__banner__dialog button.shopify-pc__banner__btn-decline {
  border: 1px solid hsl(0deg, 0%, 12%, 100%);

background: #fff;
color: #333;

}
.shopify-pc__banner__body p a:focus {
  outline: 2px solid hsl(201deg, 90%, 80%, 100%);
  box-shadow: none;
}

.shopify-pc__banner__dialog {

position: fixed;
z-index: 2000000;
box-shadow: 0px 4px 10px rgb(63 63 68 / 40%);
max-height: 90%;
box-sizing: border-box;
opacity: 1;
padding: 32px;
background-color: hsl(0deg, 0%, 100%, 100%);
overflow: auto;
-ms-overflow-style: none;
scrollbar-width: none;
border: none;
/* left is a fallback for Edge Legacy, which drops text-align: start */
text-align: left;
text-align: start;

  bottom: 0;
  left: 25%;
  width: 50%;
  min-width: 280px;
  border-top-right-radius: 3px;
  border-top-left-radius: 3px;
}

